import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import bcrypt from 'bcryptjs';
import { getSessionUser } from '@/lib/auth';

// GET: List all SCHULAMT users
export async function GET() {
  const userSession = await getSessionUser();
  if (!userSession || userSession.role !== 'ADMIN') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const schulaemter = await prisma.user.findMany({
      where: { role: 'SCHULAMT' },
      select: {
        id: true,
        email: true,
        name: true,
        role: true,
        createdAt: true,
      },
    });
    return NextResponse.json(schulaemter);
  } catch (error) {
    console.error('GET /api/admin/schulaemter error:', error);
    return NextResponse.json({ error: 'Failed to fetch' }, { status: 500 });
  }
}

// POST: Create a new SCHULAMT user
export async function POST(request: Request) {
  const userSession = await getSessionUser();
  if (!userSession || userSession.role !== 'ADMIN') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const data = await request.json();

    if (!data.email || !data.password) {
      return NextResponse.json({ error: 'E-Mail und Passwort erforderlich.' }, { status: 400 });
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(data.email)) {
      return NextResponse.json({ error: 'Ungültige E-Mail-Adresse.' }, { status: 400 });
    }

    if (typeof data.password !== 'string' || data.password.length < 6) {
      return NextResponse.json({ error: 'Passwort muss mindestens 6 Zeichen lang sein.' }, { status: 400 });
    }

    // Check for existing email
    const existing = await prisma.user.findUnique({ where: { email: data.email } });
    if (existing) {
      return NextResponse.json({ error: 'Diese E-Mail-Adresse ist bereits vergeben.' }, { status: 409 });
    }

    const hashedPassword = await bcrypt.hash(data.password, 10);

    const user = await prisma.user.create({
      data: {
        email: data.email,
        password: hashedPassword,
        role: 'SCHULAMT',
        name: data.name || null,
      },
      select: { id: true, email: true, name: true, role: true },
    });

    let latitude: number | null = null;
    let longitude: number | null = null;

    if (data.address && data.address.trim() !== '') {
      try {
        const res = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(data.address.trim())}`, {
          headers: { 'User-Agent': 'MobileReserve-App' }
        });
        if (res.ok) {
          const geoData = await res.json();
          if (geoData && geoData.length > 0) {
            latitude = parseFloat(geoData[0].lat);
            longitude = parseFloat(geoData[0].lon);
          }
        }
      } catch (err) {
        console.error('Failed to geocode new Schulamt address', err);
      }
    }

    await prisma.schulamtProfile.create({
      data: {
        userId: user.id,
        contactAddress: data.address && data.address.trim() !== '' ? data.address.trim() : "Musterstr. 1\n12345 Musterstadt",
        city: data.address && data.address.trim() !== '' ? data.address.trim() : "Musterstadt",
        latitude,
        longitude
      }
    });

    return NextResponse.json(user, { status: 201 });
  } catch (error) {
    console.error(error);
    return NextResponse.json({ error: 'Failed to create account' }, { status: 500 });
  }
}

// PATCH: Update password of a SCHULAMT user
export async function PATCH(request: Request) {
  const userSession = await getSessionUser();
  if (!userSession || userSession.role !== 'ADMIN') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { userId, newPassword } = await request.json();
    if (!userId || !newPassword) {
      return NextResponse.json({ error: 'Missing fields' }, { status: 400 });
    }

    if (typeof newPassword !== 'string' || newPassword.length < 6) {
      return NextResponse.json({ error: 'Passwort muss mindestens 6 Zeichen lang sein.' }, { status: 400 });
    }

    // Safety: only reset password for SCHULAMT users, never ADMIN
    const target = await prisma.user.findUnique({ where: { id: userId } });
    if (!target || target.role !== 'SCHULAMT') {
      return NextResponse.json({ error: 'Kann nur Passwörter von Schulamts-Accounts zurücksetzen.' }, { status: 400 });
    }

    const hashedPassword = await bcrypt.hash(newPassword, 10);
    await prisma.user.update({
      where: { id: userId },
      data: { password: hashedPassword },
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    return NextResponse.json({ error: 'Failed to update' }, { status: 500 });
  }
}

// DELETE: Remove a SCHULAMT user
export async function DELETE(request: Request) {
  const userSession = await getSessionUser();
  if (!userSession || userSession.role !== 'ADMIN') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { userId } = await request.json();
    if (!userId) {
      return NextResponse.json({ error: 'Missing userId' }, { status: 400 });
    }

    // Safety: only delete SCHULAMT users, never ADMIN
    const target = await prisma.user.findUnique({ where: { id: userId } });
    if (!target || target.role !== 'SCHULAMT') {
      return NextResponse.json({ error: 'Kann nur Schulamts-Accounts löschen.' }, { status: 400 });
    }

    await prisma.user.delete({ where: { id: userId } });
    return NextResponse.json({ success: true });
  } catch (error) {
    return NextResponse.json({ error: 'Failed to delete' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { cookies } from 'next/headers';
import bcrypt from 'bcryptjs';
import { signToken } from '@/lib/auth';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';

// Simple in-memory rate limiter for login attempts
const loginAttempts = new Map<string, { count: number; firstAttempt: number }>();
const MAX_ATTEMPTS = 5;
const WINDOW_MS = 15 * 60 * 1000; // 15 minutes

// IP-based rate limiter (broader limit per IP)
const ipLimiter = createRateLimiter({ windowMs: 15 * 60 * 1000, maxAttempts: 20 });

function cleanupAttempts(map: Map<string, {count: number; firstAttempt: number}>) {
  const now = Date.now();
  for (const [key, entry] of map) {
    if (now - entry.firstAttempt > WINDOW_MS) map.delete(key);
  }
}

function isRateLimited(email: string): boolean {
  cleanupAttempts(loginAttempts);
  const now = Date.now();
  const entry = loginAttempts.get(email);
  if (!entry || now - entry.firstAttempt > WINDOW_MS) {
    loginAttempts.set(email, { count: 1, firstAttempt: now });
    return false;
  }
  entry.count++;
  return entry.count > MAX_ATTEMPTS;
}

function resetRateLimit(email: string) {
  loginAttempts.delete(email);
}

export async function POST(request: Request) {
  try {
    const { email, password } = await request.json();

    if (!email || !password) {
      return NextResponse.json({ error: 'Email and password are required' }, { status: 400 });
    }

    // IP-based rate limiting
    const ip = getClientIp(request);
    const { success: ipAllowed } = ipLimiter.check(ip);
    if (!ipAllowed) {
      return NextResponse.json(
        { error: 'Zu viele Anmeldeversuche von dieser Adresse. Bitte warten Sie 15 Minuten.' },
        { status: 429 }
      );
    }

    const normalizedEmail = email.trim().toLowerCase();

    if (isRateLimited(normalizedEmail)) {
      return NextResponse.json(
        { error: 'Zu viele Anmeldeversuche. Bitte warten Sie 15 Minuten.' },
        { status: 429 }
      );
    }

    const user = await prisma.user.findUnique({
      where: { email: normalizedEmail },
      include: { 
        school: true, 
        teachers: {
          include: {
            assignments: {
              include: { request: { include: { school: true } } },
              orderBy: { date: 'asc' },
            },
          },
        }
      }
    });

    if (!user) {
      return NextResponse.json({ error: 'Invalid credentials' }, { status: 401 });
    }

    const isMatch = user.password.startsWith('$2') 
      ? await bcrypt.compare(password, user.password)
      : false; // No plaintext fallback – all passwords must be hashed

    if (!isMatch) {
      return NextResponse.json({ error: 'Invalid credentials' }, { status: 401 });
    }

    // Successful login: reset rate limiter
    resetRateLimit(email.toLowerCase());

    const cookieStore = await cookies();
    const token = await signToken({ id: user.id });

    cookieStore.set('session_token', token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      path: '/',
      maxAge: 60 * 60 * 24 * 7 // 1 week
    });

    const { password: _, ...userWithoutPassword } = user;
    return NextResponse.json({ success: true, user: userWithoutPassword });

  } catch (error) {
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

