import { NextResponse } from 'next/server';
import { getFullSessionUser } from '@/lib/auth';

export async function GET() {
  try {
    const user = await getFullSessionUser();

    if (!user) {
      return NextResponse.json({ user: null }, { status: 401 });
    }

    const { password: _, ...userWithoutPassword } = user;
    return NextResponse.json({ user: userWithoutPassword });
  } catch (error) {
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getSessionUser } from '@/lib/auth';

export async function GET() {
  const userSession = await getSessionUser();
  if (!userSession || userSession.role !== 'SCHULAMT') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const schulamtId = userSession.id;

    // 1. Profil abrufen
    const profile = await prisma.schulamtProfile.findUnique({
      where: { userId: schulamtId }
    });

    // 2. Schulen abrufen
    const schools = await prisma.school.findMany({
      where: { schulamtId: schulamtId }
    });
    const schoolIds = schools.map(s => s.id);

    // 3. Lehrkräfte abrufen
    const teachers = await prisma.teacher.findMany({
      where: { stammschuleId: { in: schoolIds } }
    });
    const teacherIds = teachers.map(t => t.id);

    // 4. Anforderungen abrufen
    const requests = await prisma.request.findMany({
      where: { schoolId: { in: schoolIds } }
    });
    const requestIds = requests.map(r => r.id);

    // 5. Zuweisungen abrufen
    const assignments = await prisma.assignment.findMany({
      where: { requestId: { in: requestIds } }
    });

    // 6. Fehlzeiten abrufen
    const absences = await prisma.absence.findMany({
      where: { teacherId: { in: teacherIds } }
    });

    // 7. Relevante Benutzer abrufen (Schulen und Lehrkräfte)
    // Wir holen alle User, die zu den Schulen gehören oder zu den Lehrkräften gehören.
    const usersRaw = await prisma.user.findMany({
      where: {
        OR: [
          { schoolId: { in: schoolIds } },
          { teachers: { some: { id: { in: teacherIds } } } }
        ]
      }
    });
    // Strip password hashes from backup data — imports generate new credentials anyway
    const users = usersRaw.map(({ password, ...rest }) => rest);

    // Wir speichern auch das Datum des Backups und eine Version
    const backupData = {
      version: '1.0',
      timestamp: new Date().toISOString(),
      schulamtId: schulamtId,
      data: {
        profile,
        users,
        schools,
        teachers,
        requests,
        assignments,
        absences
      }
    };

    return new NextResponse(JSON.stringify(backupData, null, 2), {
      status: 200,
      headers: {
        'Content-Type': 'application/json',
        'Content-Disposition': `attachment; filename="schulamt_backup_${new Date().toISOString().split('T')[0]}.json"`
      }
    });

  } catch (error: any) {
    console.error('Backup export failed:', error);
    return NextResponse.json({ error: 'Backup Export fehlgeschlagen', details: String(error.message || error) }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getSessionUser } from '@/lib/auth';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';

const importLimiter = createRateLimiter({ windowMs: 15 * 60 * 1000, maxAttempts: 3 });

export async function POST(request: Request) {
  const userSession = await getSessionUser();
  if (!userSession || userSession.role !== 'SCHULAMT') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const ip = getClientIp(request);
  const { success } = importLimiter.check(ip);
  if (!success) {
    return NextResponse.json(
      { error: 'Zu viele Import-Versuche. Bitte warten Sie 15 Minuten.' },
      { status: 429 }
    );
  }

  try {
    const schulamtId = userSession.id;

    // Prevent memory exhaustion from oversized payloads (max 50MB)
    const MAX_BACKUP_SIZE = 50 * 1024 * 1024;
    const contentLength = request.headers.get('content-length');
    if (contentLength && parseInt(contentLength, 10) > MAX_BACKUP_SIZE) {
      return NextResponse.json(
        { error: 'Backup-Datei ist zu groß. Maximal 50 MB erlaubt.' },
        { status: 413 }
      );
    }

    const body = await request.json();

    if (!body || !body.data || body.version !== '1.0') {
      return NextResponse.json({ error: 'Ungültiges Backup-Format' }, { status: 400 });
    }

    const {
      profile,
      users,
      schools,
      teachers,
      requests,
      assignments,
      absences
    } = body.data;

    // Führe den gesamten Import in einer Transaction durch
    await prisma.$transaction(async (tx) => {
      // 1. Alte Daten identifizieren
      const currentSchools = await tx.school.findMany({ where: { schulamtId } });
      const schoolIds = currentSchools.map(s => s.id);

      const currentTeachers = await tx.teacher.findMany({ where: { stammschuleId: { in: schoolIds } } });
      const teacherIds = currentTeachers.map(t => t.id);

      const currentRequests = await tx.request.findMany({ where: { schoolId: { in: schoolIds } } });
      const requestIds = currentRequests.map(r => r.id);

      const usersToDelete = await tx.user.findMany({
        where: {
          OR: [
            { schoolId: { in: schoolIds } },
            { teachers: { some: { id: { in: teacherIds } } } }
          ],
          role: { in: ['SCHOOL', 'TEACHER'] }
        }
      });
      const userIdsToDelete = usersToDelete.map(u => u.id);

      // 2. Alte Daten löschen (Reihenfolge ist wichtig wegen Fremdschlüsseln)
      if (requestIds.length > 0) {
        await tx.assignment.deleteMany({ where: { requestId: { in: requestIds } } });
      }
      if (teacherIds.length > 0) {
        await tx.absence.deleteMany({ where: { teacherId: { in: teacherIds } } });
      }
      if (schoolIds.length > 0) {
        await tx.request.deleteMany({ where: { schoolId: { in: schoolIds } } });
      }
      if (schoolIds.length > 0) {
        // Teacher referenziert User. Wir können Teacher gefahrlos löschen.
        await tx.teacher.deleteMany({ where: { stammschuleId: { in: schoolIds } } });
      }

      // Um Schulen zu löschen, müssen wir erst die Referenz der Users auf die Schulen lösen
      // oder die User direkt löschen (was wir sowieso vorhaben).
      // Wir setzen schoolId temporär auf null für alle betroffenen, falls es noch andere gibt.
      if (schoolIds.length > 0) {
        await tx.user.updateMany({
          where: { schoolId: { in: schoolIds } },
          data: { schoolId: null }
        });
        await tx.school.deleteMany({ where: { schulamtId } });
      }

      if (userIdsToDelete.length > 0) {
        await tx.user.deleteMany({ where: { id: { in: userIdsToDelete } } });
      }

      await tx.schulamtProfile.deleteMany({ where: { userId: schulamtId } });

      // 3. Neue Daten einfügen (Reihenfolge ist wichtig)

      // 3.1 Users
      if (users && users.length > 0) {
        // Filter out the SCHULAMT user itself
        const nonSelfUsers = users.filter((u: any) => u.id !== schulamtId);
        // SECURITY: Only allow importing SCHOOL and TEACHER roles to prevent privilege escalation
        const privilegedUsers = nonSelfUsers.filter((u: any) => u.role === 'ADMIN' || u.role === 'SCHULAMT');
        if (privilegedUsers.length > 0) {
          console.warn(
            `[SECURITY] Backup import attempted to create ${privilegedUsers.length} privileged user(s) with roles: ${privilegedUsers.map((u: any) => u.role).join(', ')}. These have been filtered out.`
          );
        }
        const safeUsers = nonSelfUsers.filter((u: any) => u.role === 'SCHOOL' || u.role === 'TEACHER');
        if (safeUsers.length > 0) {
          // Temporär schoolId entfernen, um constraint fehler zu vermeiden, da Schulen noch nicht existieren
          const usersWithoutSchoolId = safeUsers.map((u: any) => ({ ...u, schoolId: null }));
          await tx.user.createMany({ data: usersWithoutSchoolId });
        }
      }

      // 3.2 Profil
      if (profile) {
        await tx.schulamtProfile.create({ data: { ...profile, userId: schulamtId } });
      }

      // 3.3 Schulen
      if (schools && schools.length > 0) {
        const mappedSchools = schools.map((s: any) => ({ ...s, schulamtId }));
        await tx.school.createMany({ data: mappedSchools });

        // Jetzt wo Schulen da sind, können wir die schoolIds bei den Usern wieder setzen
        for (const user of users) {
          if (user.schoolId && user.id !== schulamtId) {
            await tx.user.update({
              where: { id: user.id },
              data: { schoolId: user.schoolId }
            });
          }
        }
      }

      // 3.4 Lehrkräfte
      if (teachers && teachers.length > 0) {
        await tx.teacher.createMany({ data: teachers });
      }

      // 3.5 Anforderungen
      if (requests && requests.length > 0) {
        await tx.request.createMany({ data: requests });
      }

      // 3.6 Zuweisungen
      if (assignments && assignments.length > 0) {
        await tx.assignment.createMany({ data: assignments });
      }

      // 3.7 Fehlzeiten
      if (absences && absences.length > 0) {
        await tx.absence.createMany({ data: absences });
      }
    });

    return NextResponse.json({ message: 'Backup erfolgreich wiederhergestellt' }, { status: 200 });

  } catch (error) {
    console.error('Backup import failed:', error);
    return NextResponse.json({ error: 'Wiederherstellung fehlgeschlagen. Datei fehlerhaft oder Datenbank-Konflikt.' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { rankCandidates } from '@/lib/matching';
import { getSessionUser } from '@/lib/auth';

export async function GET(
  req: Request,
  { params }: { params: Promise<{ requestId: string }> }
) {
  const userSession = await getSessionUser();
  if (!userSession || userSession.role !== 'SCHULAMT') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { requestId } = await params;

    const request = await prisma.request.findUnique({
      where: { id: requestId },
      include: { school: true },
    });

    if (!request) {
      return NextResponse.json({ error: 'Request not found' }, { status: 404 });
    }

    // Security: ensure the request belongs to this Schulamt
    if (request.school.schulamtId !== userSession.id) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    // Only load teachers from THIS Schulamt's schools
    const allTeachers = await prisma.teacher.findMany({
      where: { stammschule: { schulamtId: userSession.id } },
      include: { assignments: { select: { hours: true } } },
    });

    const ranked = rankCandidates(request, request.school, allTeachers as any);
    return NextResponse.json({ request, candidates: ranked });
  } catch (error) {
    console.error(error);
    return NextResponse.json({ error: 'Failed to match candidates' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getSessionUser } from '@/lib/auth';

export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const userSession = await getSessionUser();
  if (!userSession) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }
  if (userSession.role === 'TEACHER') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { id } = await params;

    const req = await prisma.request.findUnique({
      where: { id },
      include: { school: true, assignments: { select: { id: true } } },
    });
    if (!req) {
      return NextResponse.json({ error: 'Request not found' }, { status: 404 });
    }

    if (userSession.role === 'SCHOOL' && req.schoolId !== userSession.schoolId) {
      return NextResponse.json({ error: 'Forbidden: You can only delete your own requests.' }, { status: 403 });
    }
    if (userSession.role === 'SCHULAMT' && req.school.schulamtId !== userSession.id) {
      return NextResponse.json({ error: 'Forbidden: You can only delete requests from your own Schulamt.' }, { status: 403 });
    }

    // Guard: block deletion if active assignments exist
    if (req.assignments.length > 0) {
      return NextResponse.json(
        { error: 'Anforderung hat bereits Einsätze und kann nicht gelöscht werden. Bitte zuerst Einsätze stornieren.' },
        { status: 409 }
      );
    }

    await prisma.request.delete({ where: { id } });
    return NextResponse.json({ success: true });
  } catch (error) {
    return NextResponse.json({ error: 'Failed to delete request' }, { status: 500 });
  }
}

export const dynamic = 'force-dynamic';

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { sendEmail } from '@/lib/email';
import { getSessionUser } from '@/lib/auth';
import { getCurrentSchoolYear, getSchoolYearDates } from '@/lib/schoolYear';
import { z } from 'zod';

export async function GET(request: Request) {
  const userSession = await getSessionUser();
  if (!userSession) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

  const { searchParams } = new URL(request.url);
  let schoolId = searchParams.get('schoolId');
  const year = searchParams.get('year') || getCurrentSchoolYear();
  const { start: startDate, end: endDate } = getSchoolYearDates(year);

  if (userSession.role === 'SCHOOL') {
    if (!userSession.schoolId) return NextResponse.json({ error: 'Invalid school session' }, { status: 400 });
    schoolId = userSession.schoolId;
  } else if (userSession.role === 'TEACHER') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    let whereClause: any = schoolId ? { schoolId } : {};
    if (userSession.role === 'SCHULAMT') {
      whereClause.school = { schulamtId: userSession.id };
    }

    // Filter by school year dates
    whereClause.date = {
      gte: startDate,
      lte: endDate
    };

    const requests = await prisma.request.findMany({
      where: whereClause,
      orderBy: { date: 'asc' },
      include: {
        school: true,
        assignments: {
          include: { teacher: true }
        }
      }
    });
    return NextResponse.json(requests);
  } catch (error) {
    return NextResponse.json({ error: 'Failed to fetch requests' }, { status: 500 });
  }
}

export async function POST(request: Request) {
  const userSession = await getSessionUser();
  if (!userSession || userSession.role !== 'SCHOOL') return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

  try {
    const data = await request.json();

    const RequestSchema = z.object({
      schoolId: z.string().uuid(),
      date: z.string().refine((val) => !isNaN(new Date(val).getTime()), { message: 'Ungültiges Datum' }),
      endDate: z.string().optional().nullable(),
      priority: z.string().default('ERKRANKUNG'),
      startHour: z.union([z.string(), z.number()]).transform(v => parseInt(v as string)),
      hours: z.union([z.string(), z.number()]).transform(v => parseInt(v as string)).optional(),
      weeklyHours: z.union([z.string(), z.number()]).transform(v => parseInt(v as string)).optional(),
      schoolType: z.string().default('GRUNDSCHULE'),
      substitutedTeacher: z.string().min(1, 'Bitte geben Sie an, für wen die Vertretung benötigt wird.'),
      schedule: z.string().optional().nullable(),
      qualifications: z.string(),
      comments: z.string().min(1, 'Kommentarfeld (Startzeit/Parken) ist Pflicht.')
    });

    const parsedData = RequestSchema.safeParse(data);
    if (!parsedData.success) {
      return NextResponse.json({ error: parsedData.error.issues[0].message }, { status: 400 });
    }
    const validatedData = parsedData.data;

    if (validatedData.schoolId !== userSession.schoolId) {
      return NextResponse.json({ error: 'Unauthorized schoolId' }, { status: 401 });
    }

    const newRequest = await prisma.request.create({
      data: {
        schoolId: validatedData.schoolId,
        date: new Date(validatedData.date),
        endDate: validatedData.endDate ? new Date(validatedData.endDate) : null,
        priority: validatedData.priority,
        startHour: validatedData.startHour,
        hours: validatedData.hours || 0,
        weeklyHours: validatedData.weeklyHours || validatedData.hours || 0,
        schoolType: validatedData.schoolType,
        substitutedTeacher: validatedData.substitutedTeacher,
        schedule: validatedData.schedule || null,
        qualifications: validatedData.qualifications,
        comments: validatedData.comments,
        status: 'PENDING'
      }
    });

    const school = await prisma.school.findUnique({
      where: { id: validatedData.schoolId },
      include: { schulamt: true }
    });
    if (school) {
      const dateStr = new Date(newRequest.date).toLocaleDateString('de-DE');
      const endDateStr = newRequest.endDate ? ` bis ${new Date(newRequest.endDate).toLocaleDateString('de-DE')}` : '';
      const emailBody = `Die Schule ${school.name} hat einen Bedarf für insgesamt ${newRequest.weeklyHours} Stunden gemeldet.\n\n` +
        `Bedarfsdetails:\n` +
        `Datum: ${dateStr}${endDateStr}\n` +
        `Start (Unterrichtsstunde): ${newRequest.startHour}. Stunde\n` +
        `Schulart: ${newRequest.schoolType}\n` +
        `Zu vertreten: ${newRequest.substitutedTeacher || 'Nicht angegeben'}\n` +
        `Längerfristig: ${newRequest.schedule ? 'Ja' : 'Nein'}\n` +
        `Besonderheiten/Kommentar:\n${newRequest.comments || '-'}`;

      // Dynamically look up the schulamt user's email
      const schulamtEmail = school.schulamt?.email;
      if (schulamtEmail) {
        await sendEmail(
          schulamtEmail,
          `Neue Anforderung von ${school.name}`,
          emailBody,
          school.schulamt?.id
        );
      }
    }

    return NextResponse.json(newRequest, { status: 201 });
  } catch (error: unknown) {
    console.error(error);
    return NextResponse.json({ error: 'Ein interner Fehler ist aufgetreten.' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getSessionUser } from '@/lib/auth';
import { createRateLimiter, getClientIp } from '@/lib/rateLimit';

const resetLimiter = createRateLimiter({ windowMs: 60 * 60 * 1000, maxAttempts: 3 }); // 3 per hour

export async function POST(request: Request) {
  const userSession = await getSessionUser();
  if (!userSession || userSession.role !== 'SCHULAMT') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const ip = getClientIp(request);
  const { success } = resetLimiter.check(ip);
  if (!success) {
    return NextResponse.json(
      { error: 'Zu viele Reset-Versuche. Bitte warten Sie eine Stunde.' },
      { status: 429 }
    );
  }

  try {
    // A real app would archive these to a different table.
    // For this prototype, we'll delete the assignments, requests, and absences.
    const schools = await prisma.school.findMany({ where: { schulamtId: userSession.id }, select: { id: true } });
    const schoolIds = schools.map(s => s.id);

    const requests = await prisma.request.findMany({ where: { schoolId: { in: schoolIds } }, select: { id: true } });
    const requestIds = requests.map(r => r.id);

    const teachers = await prisma.teacher.findMany({ where: { stammschuleId: { in: schoolIds } }, select: { id: true } });
    const teacherIds = teachers.map(t => t.id);

    await prisma.$transaction([
      prisma.absence.deleteMany({ where: { teacherId: { in: teacherIds } } }),
      prisma.assignment.deleteMany({ where: { requestId: { in: requestIds } } }),
      prisma.request.deleteMany({ where: { schoolId: { in: schoolIds } } }),
      prisma.teacher.updateMany({
        where: { stammschuleId: { in: schoolIds } },
        data: { status: 'ACTIVE' }
      }),
    ]);

    return NextResponse.json({ success: true, message: "System reset successfully." });
  } catch (error) {
    return NextResponse.json({ error: 'Failed to reset system' }, { status: 500 });
  }
}

export const dynamic = 'force-dynamic';

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import bcrypt from 'bcryptjs';
import { getSessionUser } from '@/lib/auth';
import { z } from 'zod';

export async function GET() {
  const userSession = await getSessionUser();
  if (!userSession) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

  try {
    let whereClause: any = {};
    if (userSession.role === 'SCHULAMT') {
      whereClause = { schulamtId: userSession.id };
    } else if (userSession.role === 'SCHOOL' && userSession.school) {
      const school = await prisma.school.findUnique({ where: { id: userSession.school.id }, select: { schulamtId: true } });
      if (school?.schulamtId) whereClause = { schulamtId: school.schulamtId };
    } else if (userSession.role === 'TEACHER' && userSession.teachers && userSession.teachers.length > 0) {
      const schulamtIds = userSession.teachers
        .map(t => t.stammschule?.schulamtId)
        .filter((id): id is string => !!id);
      if (schulamtIds.length > 0) {
        whereClause = { schulamtId: { in: schulamtIds } };
      } else {
        whereClause = { id: 'none' };
      }
    } else if (userSession.role !== 'ADMIN') {
      whereClause = { id: 'none' };
    }
    const schools = await prisma.school.findMany({
      where: whereClause,
      select: {
        id: true,
        name: true,
        address: true,
        latitude: true,
        longitude: true,
        type: true,
        generalInfo: true,
        imageUrl: true,
        pinLat: true,
        pinLng: true,
        user: userSession.role === 'SCHULAMT' ? {
          select: { id: true, email: true, role: true }
        } : false,
      }
    });
    return NextResponse.json(schools);
  } catch (error) {
    return NextResponse.json({ error: 'Failed to fetch schools' }, { status: 500 });
  }
}

export async function POST(request: Request) {
  const userSession = await getSessionUser();
  if (!userSession || userSession.role !== 'SCHULAMT') return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

  try {
    const data = await request.json();

    const SchoolSchema = z.object({
      name: z.string().min(1, 'Schulname ist erforderlich'),
      address: z.string().min(1, 'Adresse ist erforderlich'),
      type: z.enum(['GRUNDSCHULE', 'MITTELSCHULE']),
      email: z.string().email('Ungültige E-Mail-Adresse').optional().nullable(),
      password: z.string().min(6, 'Passwort muss mindestens 6 Zeichen lang sein'),
      latitude: z.number().optional().nullable(),
      longitude: z.number().optional().nullable(),
    });

    const parsedData = SchoolSchema.safeParse(data);
    if (!parsedData.success) {
      return NextResponse.json({ error: parsedData.error.issues[0].message }, { status: 400 });
    }
    const validatedData = parsedData.data;

    let lat = validatedData.latitude || 48.0;
    let lng = validatedData.longitude || 10.5;

    if (validatedData.address && !validatedData.latitude) {
      try {
        const res = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(validatedData.address)}`, {
          headers: { 'User-Agent': 'MobileReservenApp/1.0' }
        });
        const geo = await res.json();
        if (geo && geo.length > 0) {
          lat = parseFloat(geo[0].lat);
          lng = parseFloat(geo[0].lon);
        }
      } catch (e) {
        console.error("Geocoding failed for school:", e);
      }
    }

    const rawEmail = validatedData.email || `${validatedData.name.toLowerCase().replace(/[^a-z0-9]/g, '')}@schule.de`;
    const email = rawEmail.trim().toLowerCase();
    const hashedPassword = await bcrypt.hash(validatedData.password, 10);

    const school = await prisma.school.create({
      data: {
        name: validatedData.name,
        address: validatedData.address,
        type: validatedData.type,
        latitude: lat,
        longitude: lng,
        schulamtId: userSession.id,
        user: {
          create: {
            email: email,
            password: hashedPassword,
            role: 'SCHOOL'
          }
        }
      },
      include: { 
        user: {
          select: { id: true, email: true, role: true }
        } 
      }
    });

    return NextResponse.json(school, { status: 201 });
  } catch (error) {
    console.error(error);
    return NextResponse.json({ error: 'Failed to create school' }, { status: 500 });
  }
}

export async function PATCH(request: Request) {
  const userSession = await getSessionUser();
  if (!userSession) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

  try {
    const data = await request.json();

    if (data.action === 'updateInfo') {
      if (userSession.role !== 'SCHOOL' && userSession.role !== 'SCHULAMT') {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
      }
      const { schoolId, generalInfo, imageUrl, pinLat, pinLng } = data;
      if (userSession.role === 'SCHOOL' && userSession.schoolId !== schoolId) {
        return NextResponse.json({ error: 'Forbidden: You can only update your own school profile.' }, { status: 403 });
      }

      // Validate imageUrl: must start with /uploads/ or be empty/null
      if (imageUrl && !imageUrl.startsWith('/uploads/')) {
        return NextResponse.json({ error: 'Ungültige Bild-URL.' }, { status: 400 });
      }

      if (userSession.role === 'SCHULAMT') {
        const schoolCheck = await prisma.school.findUnique({ where: { id: schoolId } });
        if (!schoolCheck || schoolCheck.schulamtId !== userSession.id) {
          return NextResponse.json({ error: 'Forbidden: School does not belong to your Schulamt.' }, { status: 403 });
        }
      }
      const school = await prisma.school.update({
        where: { id: schoolId },
        data: {
          generalInfo,
          imageUrl: imageUrl || null,
          pinLat,
          pinLng
        }
      });
      return NextResponse.json({ success: true, school });
    }

    if (!data.schoolId) {
      return NextResponse.json({ error: 'Missing schoolId' }, { status: 400 });
    }

    if (!data.newPassword && !data.newEmail) {
      return NextResponse.json({ error: 'Missing newPassword or newEmail' }, { status: 400 });
    }

    // Find the user for this school
    const user = await prisma.user.findUnique({
      where: { schoolId: data.schoolId }
    });

    if (!user) {
      return NextResponse.json({ error: 'User for this school not found' }, { status: 404 });
    }

    if (userSession.role !== 'SCHULAMT') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const schoolCheck = await prisma.school.findUnique({ where: { id: data.schoolId } });
    if (!schoolCheck || schoolCheck.schulamtId !== userSession.id) {
      return NextResponse.json({ error: 'Forbidden: School does not belong to your Schulamt.' }, { status: 403 });
    }

    const updateData: any = {};
    if (data.newPassword) {
      if (typeof data.newPassword !== 'string' || data.newPassword.length < 6) {
        return NextResponse.json({ error: 'Passwort muss mindestens 6 Zeichen lang sein.' }, { status: 400 });
      }
      updateData.password = await bcrypt.hash(data.newPassword, 10);
    }
    if (data.newEmail) {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(data.newEmail)) {
        return NextResponse.json({ error: 'Ungültige E-Mail-Adresse.' }, { status: 400 });
      }
      updateData.email = data.newEmail.trim().toLowerCase();
    }

    const updatedUser = await prisma.user.update({
      where: { id: user.id },
      data: updateData,
      select: { id: true, email: true, role: true }
    });

    return NextResponse.json({ success: true, user: updatedUser });
  } catch (error) {
    console.error(error);
    return NextResponse.json({ error: 'Failed to update password' }, { status: 500 });
  }
}

