export async function GET() {
  const userSession = await getSessionUser();
  if (!userSession || (userSession.role !== 'SCHULAMT' && userSession.role !== 'ADMIN')) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const settings = await prisma.systemSetting.findMany();
    // Convert array of { id, value } to an object
    const settingsObj = settings.reduce((acc, curr) => {
      acc[curr.id] = curr.value;
      return acc;
    }, {} as Record<string, string>);

    // Mask SMTP password before returning
    if (settingsObj['smtpPass']) {
      settingsObj['smtpPass'] = '********';
    }

    return NextResponse.json(settingsObj);
  } catch (error) {
    return NextResponse.json({ error: 'Failed to fetch settings' }, { status: 500 });
  }
}

export async function POST(request: Request) {
  const userSession = await getSessionUser();
  if (!userSession || userSession.role !== 'ADMIN') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const data = await request.json();

    // data is expected to be an object of key-value pairs
    // Update or create each setting
    const ALLOWED_SETTINGS = ['smtpHost', 'smtpUser', 'smtpPass', 'impressum'];

    for (const [key, value] of Object.entries(data)) {
      if (typeof value === 'string' && ALLOWED_SETTINGS.includes(key)) {
        // If the frontend sends back the masked password, don't overwrite the real one
        if (key === 'smtpPass' && (value === '********' || value === '')) {
          continue;
        }
        await prisma.systemSetting.upsert({
          where: { id: key },
          update: { value },
          create: { id: key, value }
        });
      }
    }

    return NextResponse.json({ success: true });
  } catch (error) {
    return NextResponse.json({ error: 'Failed to save settings' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getSessionUser } from '@/lib/auth';

export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const userSession = await getSessionUser();
  if (!userSession) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const { id } = await params;

  // Only SCHULAMT or the teacher themselves can view assignment history
  if (userSession.role === 'SCHOOL') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  if (userSession.role === 'TEACHER' && !userSession.teachers?.some(t => t.id === id)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  if (userSession.role === 'SCHULAMT') {
    const teacherCheck = await prisma.teacher.findUnique({ where: { id: id }, include: { stammschule: true } });
    if (!teacherCheck || teacherCheck.stammschule?.schulamtId !== userSession.id) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }
  }

  try {
    const assignments = await prisma.assignment.findMany({
      where: { teacherId: id },
      include: {
        request: {
          include: {
            school: true
          }
        }
      },
      orderBy: {
        date: 'desc'
      }
    });

    return NextResponse.json(assignments);
  } catch (error) {
    return NextResponse.json({ error: 'Failed to fetch assignments' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getSessionUser } from '@/lib/auth';
import * as XLSX from 'xlsx';

export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const userSession = await getSessionUser();
  if (!userSession) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const { id } = await params;

  // Only SCHULAMT or the teacher themselves can view assignment history
  if (userSession.role === 'SCHOOL') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  if (userSession.role === 'TEACHER' && !userSession.teachers?.some((t: any) => t.id === id)) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  if (userSession.role === 'SCHULAMT') {
    const teacherCheck = await prisma.teacher.findUnique({ where: { id: id }, include: { stammschule: true } });
    if (!teacherCheck || teacherCheck.stammschule?.schulamtId !== userSession.id) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }
  }

  try {
    const teacher = await prisma.teacher.findUnique({ where: { id: id } });
    if (!teacher) return NextResponse.json({ error: 'Not found' }, { status: 404 });

    const assignments = await prisma.assignment.findMany({
      where: { teacherId: id },
      include: {
        request: {
          include: {
            school: true
          }
        }
      },
      orderBy: {
        date: 'desc'
      }
    });

    // Generate XLSX
    const data = assignments.map(a => ({
      Datum: new Date(a.date).toLocaleDateString('de-DE'),
      Schule: a.request.school.name,
      'Fach/Klassen': a.request.qualifications,
      Einsatzstunden: a.hours,
      Status: a.status
    }));

    const worksheet = XLSX.utils.json_to_sheet(data);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Einsätze');

    // Adjust column widths
    worksheet['!cols'] = [
      { wch: 12 }, // Datum
      { wch: 30 }, // Schule
      { wch: 25 }, // Fach/Klassen
      { wch: 15 }, // Einsatzstunden
      { wch: 15 }, // Status
    ];

    const buffer = XLSX.write(workbook, { type: 'buffer', bookType: 'xlsx' });
    const fileName = `Einsaetze_${teacher.name.replace(/[^a-z0-9]/gi, '_')}.xlsx`;

    return new NextResponse(buffer, {
      headers: {
        'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'Content-Disposition': `attachment; filename="${fileName}"`,
      },
    });

  } catch (error) {
    return NextResponse.json({ error: 'Failed to generate export' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import bcrypt from 'bcryptjs';
import { getSessionUser } from '@/lib/auth';
import { z } from 'zod';

export async function PATCH(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const userSession = await getSessionUser();
  if (!userSession || userSession.role !== 'SCHULAMT') return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  try {
    const p = await params;
    const data = await request.json();

    const TeacherUpdateSchema = z.object({
      name: z.string().min(1, 'Name ist erforderlich').optional(),
      email: z.string().email().optional().nullable(),
      phone: z.string().optional().nullable(),
      stammschuleId: z.string().uuid('Ungültige Schul-ID').optional(),
      maxWeeklyHours: z.union([z.string(), z.number()]).transform(v => parseInt(v as string)).optional(),
      isPartTime: z.boolean().optional(),
      schedule: z.any().optional().nullable(),
      qualifications: z.string().optional(),
      status: z.string().optional(),
      address: z.string().optional().nullable(),
      gender: z.enum(['FEMALE', 'MALE', 'DIVERSE']).optional().nullable(),
      homeLat: z.union([z.string(), z.number()]).transform(v => parseFloat(v as string)).optional(),
      homeLng: z.union([z.string(), z.number()]).transform(v => parseFloat(v as string)).optional(),
      preferredType: z.enum(['GRUNDSCHULE', 'MITTELSCHULE', 'BOTH']).optional(),
      password: z.string().optional().nullable(),
    });

    const parsedData = TeacherUpdateSchema.safeParse(data);
    if (!parsedData.success) {
      return NextResponse.json({ error: parsedData.error.issues[0].message }, { status: 400 });
    }
    const validatedData = parsedData.data;

    const existingTeacher = await prisma.teacher.findUnique({
      where: { id: p.id },
      include: { stammschule: true }
    });

    if (!existingTeacher || existingTeacher.stammschule?.schulamtId !== userSession.id) {
      return NextResponse.json({ error: 'Forbidden: You can only modify teachers from your own Schulamt.' }, { status: 403 });
    }

    const isFullUpdate = validatedData.name !== undefined;
    let finalData: any = { ...validatedData };
    delete finalData.password;

    if (isFullUpdate) {
      let lat = validatedData.homeLat;
      let lng = validatedData.homeLng;

      if (validatedData.address) {
        const res = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(validatedData.address)}`, {
          headers: { 'User-Agent': 'MobileReservenApp/1.0' }
        });
        const geo = await res.json();
        if (geo && geo.length > 0) {
          lat = parseFloat(geo[0].lat);
          lng = parseFloat(geo[0].lon);
        }
      }

      finalData = {
        name: validatedData.name,
        email: validatedData.email || null,
        phone: validatedData.phone || null,
        stammschuleId: validatedData.stammschuleId,
        maxWeeklyHours: validatedData.maxWeeklyHours !== undefined ? validatedData.maxWeeklyHours : existingTeacher.maxWeeklyHours,
        isPartTime: validatedData.isPartTime !== undefined ? validatedData.isPartTime : existingTeacher.isPartTime,
        schedule: validatedData.isPartTime && validatedData.schedule ? JSON.stringify(validatedData.schedule) : null,
        qualifications: validatedData.qualifications !== undefined ? validatedData.qualifications : existingTeacher.qualifications,
        status: validatedData.status || 'ACTIVE',
        preferredType: validatedData.preferredType !== undefined ? validatedData.preferredType : existingTeacher.preferredType,
        gender: validatedData.gender || null,
      };

      if (lat && lng) {
        finalData.homeLat = lat;
        finalData.homeLng = lng;
      }
    }

    const teacher = await prisma.teacher.update({
      where: { id: p.id },
      data: finalData
    });

    if (isFullUpdate && validatedData.password) {
      const rawEmail = validatedData.email || `${validatedData.name?.toLowerCase().replace(/[^a-z0-9]/g, '')}@lehrer.de`;
      const userEmail = rawEmail.trim().toLowerCase();
      const hashedPassword = await bcrypt.hash(validatedData.password, 10);
      let user = teacher.userId ? await prisma.user.findUnique({ where: { id: teacher.userId } }) : null;
      if (user) {
        await prisma.user.update({
          where: { id: user.id },
          data: { email: userEmail, password: hashedPassword }
        });
      } else {
        const newUser = await prisma.user.create({
          data: { email: userEmail, password: hashedPassword, role: 'TEACHER' }
        });
        await prisma.teacher.update({ where: { id: p.id }, data: { userId: newUser.id } });
      }
    } else if (isFullUpdate && validatedData.email) {
       let user = teacher.userId ? await prisma.user.findUnique({ where: { id: teacher.userId } }) : null;
       if (user) {
         await prisma.user.update({
           where: { id: user.id },
           data: { email: validatedData.email.trim().toLowerCase() }
         });
       }
    }

    return NextResponse.json(teacher);
  } catch (error) {
    return NextResponse.json({ error: 'Failed to update teacher' }, { status: 500 });
  }
}

export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const userSession = await getSessionUser();
  if (!userSession || userSession.role !== 'SCHULAMT') return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

  try {
    const p = await params;

    const existingTeacher = await prisma.teacher.findUnique({
      where: { id: p.id },
      include: { stammschule: true }
    });

    if (!existingTeacher || existingTeacher.stammschule?.schulamtId !== userSession.id) {
      return NextResponse.json({ error: 'Forbidden: You can only delete teachers from your own Schulamt.' }, { status: 403 });
    }

    await prisma.teacher.delete({
      where: { id: p.id }
    });

    // Delete associated user account if exists
    if (existingTeacher.userId) {
      await prisma.user.delete({
        where: { id: existingTeacher.userId }
      });
    }

    return NextResponse.json({ success: true });
  } catch (error) {
    return NextResponse.json({ error: 'Failed to delete teacher' }, { status: 500 });
  }
}

export const dynamic = 'force-dynamic';

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import bcrypt from 'bcryptjs';
import { getSessionUser } from '@/lib/auth';
import { getCurrentSchoolYear } from '@/lib/schoolYear';
import { z } from 'zod';

export async function GET(request: Request) {
  const userSession = await getSessionUser();
  if (!userSession) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

  // Privacy: Teachers can only see their own profile? Or maybe they don't even use this endpoint.
  // Actually, only SCHULAMT and SCHOOL need the full list.
  if (userSession.role === 'TEACHER') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const { searchParams } = new URL(request.url);
  const year = searchParams.get('year') || getCurrentSchoolYear();

  try {
    let whereClause: any = {};
    if (userSession.role === 'SCHULAMT') {
      whereClause = { stammschule: { schulamtId: userSession.id } };
    } else if (userSession.role === 'SCHOOL' && userSession.school) {
      const school = await prisma.school.findUnique({ where: { id: userSession.school.id }, select: { schulamtId: true } });
      if (school?.schulamtId) {
        whereClause = { stammschule: { schulamtId: school.schulamtId } };
      } else {
        whereClause = { id: 'none' };
      }
    } else if (userSession.role !== 'ADMIN') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }
    whereClause.schoolYear = year;

    const teachers = await prisma.teacher.findMany({
      where: whereClause,
      include: {
        stammschule: true,
        assignments: true,
      }
    });
    return NextResponse.json(teachers);
  } catch (error) {
    return NextResponse.json({ error: 'Failed to fetch teachers' }, { status: 500 });
  }
}

export async function POST(request: Request) {
  const userSession = await getSessionUser();
  if (!userSession || userSession.role !== 'SCHULAMT') return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });

  try {
    const data = await request.json();

    const TeacherSchema = z.object({
      name: z.string().min(1, 'Name ist erforderlich'),
      email: z.string().email().optional().nullable(),
      phone: z.string().optional().nullable(),
      stammschuleId: z.string().uuid('Ungültige Schul-ID'),
      maxWeeklyHours: z.union([z.string(), z.number()]).transform(v => parseInt(v as string)),
      isPartTime: z.boolean().optional().default(false),
      schedule: z.any().optional().nullable(),
      qualifications: z.string(),
      status: z.string().optional().default('ACTIVE'),
      address: z.string().optional().nullable(),
      gender: z.enum(['FEMALE', 'MALE', 'DIVERSE']).optional().nullable(),
      homeLat: z.union([z.string(), z.number()]).transform(v => parseFloat(v as string)).optional(),
      homeLng: z.union([z.string(), z.number()]).transform(v => parseFloat(v as string)).optional(),
      preferredType: z.enum(['GRUNDSCHULE', 'MITTELSCHULE', 'BOTH']),
      schoolYear: z.string().optional().nullable(),
      password: z.string().min(6, 'Passwort muss mindestens 6 Zeichen lang sein').optional().nullable(),
    });

    const parsedData = TeacherSchema.safeParse(data);
    if (!parsedData.success) {
      return NextResponse.json({ error: parsedData.error.issues[0].message }, { status: 400 });
    }
    const validatedData = parsedData.data;

    let lat = 48.01; // Fallback
    let lng = 10.5;  // Fallback

    if (validatedData.address) {
      // Geocode using OpenStreetMap Nominatim
      const res = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(validatedData.address)}`, {
        headers: {
          'User-Agent': 'MobileReservenApp/1.0' // Required by Nominatim policy
        }
      });
      const geo = await res.json();
      if (geo && geo.length > 0) {
        lat = parseFloat(geo[0].lat);
        lng = parseFloat(geo[0].lon);
      } else {
        return NextResponse.json({ error: 'Adresse konnte nicht gefunden werden.' }, { status: 400 });
      }
    } else if (validatedData.homeLat !== undefined && validatedData.homeLng !== undefined) {
      lat = validatedData.homeLat;
      lng = validatedData.homeLng;
    }

    const teacher = await prisma.teacher.create({
      data: {
        name: validatedData.name,
        email: validatedData.email || null,
        phone: validatedData.phone || null,
        stammschuleId: validatedData.stammschuleId,
        maxWeeklyHours: validatedData.maxWeeklyHours,
        isPartTime: validatedData.isPartTime,
        schedule: validatedData.isPartTime && validatedData.schedule ? JSON.stringify(validatedData.schedule) : null,
        qualifications: validatedData.qualifications,
        status: validatedData.status,
        address: validatedData.address || '',
        gender: validatedData.gender || null,
        homeLat: lat,
        homeLng: lng,
        preferredType: validatedData.preferredType,
        schoolYear: validatedData.schoolYear || getCurrentSchoolYear(),
      }
    });

    if (validatedData.password) {
      const rawEmail = validatedData.email || `${validatedData.name.toLowerCase().replace(/[^a-z0-9]/g, '')}@lehrer.de`;
      const userEmail = rawEmail.trim().toLowerCase();
      const hashedPassword = await bcrypt.hash(validatedData.password, 10);
      const newUser = await prisma.user.create({
        data: {
          email: userEmail,
          password: hashedPassword,
          role: 'TEACHER',
        }
      });
      await prisma.teacher.update({ where: { id: teacher.id }, data: { userId: newUser.id } });
    }

    return NextResponse.json(teacher, { status: 201 });
  } catch (error) {
    return NextResponse.json({ error: 'Failed to create teacher' }, { status: 500 });
  }
}

