        <Marker position={[school.latitude, school.longitude]} icon={customSchoolIcon}>
          <Popup>
            <strong>{school.name}</strong><br/>
            Haupteingang
          </Popup>
        </Marker>

        {/* Parking Pin */}
        {hasParking && (
          <Marker position={[school.pinLat, school.pinLng]} icon={customParkingIcon}>
            <Popup>
              <strong>Parkplatz</strong><br/>
              Für Mobile Reserven
            </Popup>
          </Marker>
        )}
      </MapContainer>
    </div>
  );
}

