import React, { useMemo } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { TeacherData, RequestData } from '@/types/models';

export function Statistics({ teachers, requests }: { teachers: TeacherData[], requests: RequestData[] }) {

  // 1. Auslastung der Lehrkräfte
  const utilizationData = useMemo(() => {
    return teachers.map(t => {
      const assigned = t.assignedHours || 0;
      return {
        name: t.name,
        'Max. Stunden': t.maxWeeklyHours,
        'Verplante Stunden': assigned,
        'Freie Stunden': Math.max(0, t.maxWeeklyHours - assigned)
      };
    });
  }, [teachers]);

  // 2. Bedarfsgründe
  const priorityData = useMemo(() => {
    const counts: Record<string, number> = {
      'Ungeplanter Ausfall': 0,
      'Geplant / Mutterschutz': 0,
      'Fortbildung': 0,
      'Sonstiges': 0
    };
    requests.forEach(r => {
      if (r.priority === 'ERKRANKUNG') counts['Ungeplanter Ausfall']++;
      else if (r.priority === 'MUTTERSCHUTZ') counts['Geplant / Mutterschutz']++;
      else if (r.priority === 'FORTBILDUNG') counts['Fortbildung']++;
      else counts['Sonstiges']++;
    });
    return Object.entries(counts).filter(([_, count]) => count > 0).map(([name, value]) => ({ name, value }));
  }, [requests]);

  // 3. Bedarf nach Schulart
  const schoolTypeData = useMemo(() => {
    const counts: Record<string, number> = {
      'Grundschule': 0,
      'Mittelschule': 0,
      'Unbekannt': 0
    };
    requests.forEach(r => {
      if (r.schoolType === 'GRUNDSCHULE') counts['Grundschule']++;
      else if (r.schoolType === 'MITTELSCHULE') counts['Mittelschule']++;
      else counts['Unbekannt']++;
    });
    return Object.entries(counts).filter(([_, count]) => count > 0).map(([name, value]) => ({ name, value }));
  }, [requests]);

  const COLORS = ['#f97316', '#3b82f6', '#10b981', '#f43f5e', '#8b5cf6'];

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">

        {/* Priority Pie Chart */}
        <Card>
          <CardHeader>
            <CardTitle className="text-slate-700 dark:text-slate-200">Gründe für Anforderungen</CardTitle>
          </CardHeader>
          <CardContent className="h-[300px]">
            {priorityData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={priorityData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value" label>
                    {priorityData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            ) : (
              <div className="flex h-full items-center justify-center text-slate-500">Keine Daten vorhanden</div>
            )}
          </CardContent>
        </Card>

        {/* SchoolType Pie Chart */}
        <Card>
          <CardHeader>
            <CardTitle className="text-slate-700 dark:text-slate-200">Bedarf nach Schulart</CardTitle>
          </CardHeader>
          <CardContent className="h-[300px]">
             {schoolTypeData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={schoolTypeData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value" label>
                    {schoolTypeData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
             ) : (
                <div className="flex h-full items-center justify-center text-slate-500">Keine Daten vorhanden</div>
             )}
          </CardContent>
        </Card>

        {/* Utilization Bar Chart */}
        <Card className="md:col-span-2">
          <CardHeader>
            <CardTitle className="text-slate-700 dark:text-slate-200">Auslastung der Mobilen Reserven</CardTitle>
          </CardHeader>
          <CardContent className="h-[400px]">
             {utilizationData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={utilizationData} margin={{ top: 20, right: 30, left: 0, bottom: 50 }}>
                  <CartesianGrid strokeDasharray="3 3" opacity={0.2} />
                  <XAxis dataKey="name" angle={-45} textAnchor="end" height={80} />
                  <YAxis />
                  <Tooltip />
                  <Legend verticalAlign="top" height={36}/>
                  <Bar dataKey="Verplante Stunden" stackId="a" fill="#f97316" />
                  <Bar dataKey="Freie Stunden" stackId="a" fill="#e2e8f0" />
                </BarChart>
              </ResponsiveContainer>
             ) : (
               <div className="flex h-full items-center justify-center text-slate-500">Keine Daten vorhanden</div>
             )}
          </CardContent>
        </Card>

      </div>
    </div>
  );
}

import { cookies } from 'next/headers';
import { prisma } from './prisma';
import { jwtVerify, SignJWT } from 'jose';

function getKey() {
  const secretKey = process.env.JWT_SECRET;
  if (!secretKey) {
    throw new Error('JWT_SECRET environment variable is required');
  }
  return new TextEncoder().encode(secretKey);
}

export async function signToken(payload: { id: string }) {
  return await new SignJWT(payload)
    .setProtectedHeader({ alg: 'HS256' })
    .setIssuedAt()
    .setExpirationTime('24h')
    .sign(getKey());
}

export async function verifyToken(token: string) {
  try {
    const { payload } = await jwtVerify(token, getKey());
    return payload as { id: string };
  } catch (error) {
    return null;
  }
}

/**
 * Lightweight session lookup – used in all API routes for auth checks.
 * Only fetches school/teacher IDs + role; no heavy assignment joins.
 */
export async function getSessionUser() {
  const cookieStore = await cookies();
  const token = cookieStore.get('session_token')?.value;
  if (!token) return null;

  const payload = await verifyToken(token);
  if (!payload || !payload.id) return null;

  return prisma.user.findUnique({
    where: { id: payload.id },
    include: {
      school: { select: { id: true, schulamtId: true } },
      teachers: { select: { id: true, schoolYear: true, stammschule: { select: { schulamtId: true } } } },
    },
  });
}

/**
 * Full session lookup – only used by /api/auth/me to hydrate the client session.
 * Loads full assignment history for the TeacherDashboard.
 */
export async function getFullSessionUser() {
  const cookieStore = await cookies();
  const token = cookieStore.get('session_token')?.value;
  if (!token) return null;

  const payload = await verifyToken(token);
  if (!payload || !payload.id) return null;

  return prisma.user.findUnique({
    where: { id: payload.id },
    include: {
      school: true,
      teachers: {
        include: {
          assignments: {
            include: { request: { include: { school: true } } },
            orderBy: { date: 'asc' },
          },
        },
      },
    },
  });
}

import { Teacher, School, Request } from '@prisma/client'

// Earth radius in kilometers
const R = 6371

// Haversine formula to calculate distance between two lat/lng coordinates in km
export function calculateDistance(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const dLat = (lat2 - lat1) * (Math.PI / 180)
  const dLon = (lon2 - lon1) * (Math.PI / 180)
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(lat1 * (Math.PI / 180)) * Math.cos(lat2 * (Math.PI / 180)) *
    Math.sin(dLon / 2) * Math.sin(dLon / 2)
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
  return R * c
}

export type TeacherWithDistance = Teacher & {
  distanceToSchool: number;
  matchScore: number;
  assignedHours: number; // dynamically computed
}

// Rank candidates based on Priority Logic
export function rankCandidates(
  request: Request,
  requestingSchool: School,
  allTeachers: (Teacher & { assignments: { hours: number; date: Date }[] })[]
): TeacherWithDistance[] {

  const eligibleTeachers: TeacherWithDistance[] = []

  // Calculate current week boundaries (Monday to Sunday)
  const now = new Date();
  const weekStart = new Date(now);
  weekStart.setDate(now.getDate() - now.getDay() + 1); // Monday
  weekStart.setHours(0,0,0,0);
  const weekEnd = new Date(weekStart);
  weekEnd.setDate(weekStart.getDate() + 6);
  weekEnd.setHours(23,59,59,999);

  for (const teacher of allTeachers) {
    // b) Hard Filter: Sick/Leave status
    if (teacher.status !== 'ACTIVE') continue

    // Calculate current weekly hours (filtered to current week only)
    const currentHours = teacher.assignments
      .filter(a => { const d = new Date(a.date); return d >= weekStart && d <= weekEnd; })
      .reduce((sum, a) => sum + a.hours, 0)

    // Check Max Weekly Hours - Allow if they have ANY capacity left for partial matching
    if (currentHours >= teacher.maxWeeklyHours) continue

    // d) Check Part-Time Schedule Match
    if (teacher.isPartTime && teacher.schedule) {
      try {
        const schedule = JSON.parse(teacher.schedule);
        const reqStart = new Date(request.date);
        const reqEnd = request.endDate ? new Date(request.endDate) : reqStart;

        let isAvailable = true;
        const reqSchedule = request.schedule ? JSON.parse(request.schedule) : null;

        // Loop through each day in the requested period
        for (let d = new Date(reqStart); d <= reqEnd; d.setDate(d.getDate() + 1)) {
          const dayOfWeek = d.getDay() === 0 ? 7 : d.getDay(); // 1=Mon, 7=Sun
          if (dayOfWeek > 5) continue; // Skip weekends

          // The required hours for each day
          let requiredHours: number[] = [];
          if (reqSchedule) {
            requiredHours = reqSchedule[dayOfWeek.toString()] || [];
          } else {
            requiredHours = Array.from({ length: request.hours }, (_, i) => request.startHour + i);
          }

          // If no hours required on this day, skip check
          if (requiredHours.length === 0) continue;

          // Check if teacher schedule has all required hours for this dayOfWeek
          const teacherDaySchedule = schedule[dayOfWeek.toString()] || [];
          const hasHours = requiredHours.every(h => teacherDaySchedule.includes(h));

          if (!hasHours) {
            isAvailable = false;
            break;
          }
        }

        if (!isAvailable) continue;
      } catch (e) {
        console.error("Invalid schedule JSON for teacher", teacher.id);
        continue;
      }
    }

    // c) Qualifications Match (Soft Filter)
    const reqQuals = request.qualifications.split(',').filter(Boolean)
    const teacherQuals = teacher.qualifications.split(',').filter(Boolean)

    // If teacher has "Alles", they perfectly match any qualification.
    const hasAllQuals = teacherQuals.includes('Alles') || 
      (reqQuals.length === 0) || 
      reqQuals.every(q => teacherQuals.includes(q));

    const distance = calculateDistance(requestingSchool.latitude, requestingSchool.longitude, teacher.homeLat, teacher.homeLng)

    let score = 0
    // a) Priority 1: Stammschule
    if (teacher.stammschuleId === requestingSchool.id) {
      score += 1000 // Huge boost for Stammschule
    }

    // b) Priority 2: Qualifications Match
    if (hasAllQuals) {
      score += 500 // Significant boost for having the exact requested qualification or 'Alles'
    }

    // preferredType scoring
    if (teacher.preferredType) {
      if (teacher.preferredType === request.schoolType) {
        score += 15;
      } else if (teacher.preferredType !== 'BOTH') {
        score -= 10;
      }
    }

    // Add inverse distance as a tie-breaker (closer = higher score)
    score += 100 / (1 + distance)

    eligibleTeachers.push({
      ...teacher,
      distanceToSchool: distance,
      matchScore: score,
      assignedHours: currentHours
    })
  }

  // Sort by highest score first
  return eligibleTeachers.sort((a, b) => b.matchScore - a.matchScore)
}
